from datetime import datetime
import calendar

def next_due_date(last_inspection: str, remaining_life_yr: float, max_interval_yr: int) -> str:
    if max_interval_yr < 1:
        raise ValueError("max_interval_yr must be at least 1 year.")

    try:
        last_inspection_dt = datetime.strptime(last_inspection, "%d-%m-%Y")
    except ValueError:
        raise ValueError("last_inspection must be a valid date in 'DD-MM-YYYY' format.")

    if remaining_life_yr <= 0:
        return last_inspection

    half_life = remaining_life_yr / 2
    interval = min(half_life, max_interval_yr)
    interval = max(1, int(interval))  # Ensure at least 1 year

    try:
        next_due_dt = last_inspection_dt.replace(year=last_inspection_dt.year + interval)
    except ValueError:  # Handle February 29 edge case
        # Find the last valid day of the month for the target date
        while True:
            try:
                next_due_dt = last_inspection_dt.replace(year=last_inspection_dt.year + interval, 
                                                         day=last_inspection_dt.day, 
                                                         month=last_inspection_dt.month)
                break
            except ValueError:
                # Move to the previous month and set day to the last day of that month
                if last_inspection_dt.month == 2 and last_inspection_dt.day == 29:
                    next_due_dt = datetime(last_inspection_dt.year + interval, 2, 28)
                else:
                    last_inspection_dt = last_inspection_dt.replace(day=calendar.monthrange(last_inspection_dt.year + interval, 
                                                                                          last_inspection_dt.month)[1])

    return next_due_dt.strftime("%d-%m-%Y")
